def split_upperstring(s):
    result = []
    current = ""
    for char in s:
        if char.isupper():
            if current:
                result.append(current)
                current = ""
            current += char
        else:
            current += char
    if current:
        result.append(current)
    return result

# Test case
print(split_upperstring("PythonProgramLanguage"))  # Expected: ['Python', 'Program', 'Language']
```

