def count_element_freq(mixed_tuple):
    """
    Count the frequency of each element in a mixed nested tuple.

    Parameters:
    - mixed_tuple: A tuple that may contain elements and other tuples recursively.

    Returns:
        A dictionary where keys are elements and values are their frequencies in the entire structure.
    """
    freq = {}

    def traverse(element):
        if isinstance(element, tuple):
            for item in element:
                traverse(item)
        else:
            # Update frequency for non-tuple elements
            if element in freq:
                freq[element] += 1
            else:
                freq[element] = 1

    traverse(mixed_tuple)
    return freq

