import re

def num_position(s):
    """
    Return the starting index (0‑based) of the first occurrence of a sequence of digits (a number)
    in the input string `s`.  If no digits are found, return -1.
    """
    match = re.search(r'\d+', s)
    if match:
        return match.start()
    else:
        return -1
